CREATE TABLE IF NOT EXISTS psp_runs(id varchar(80) PRIMARY KEY,policy varchar(16) NOT NULL,controls jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS psp_payments(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL REFERENCES psp_runs,attempt_id uuid NOT NULL,provider_order_id varchar(64) NOT NULL,merchant varchar(32) NOT NULL DEFAULT 'payment-lab',environment varchar(16) NOT NULL DEFAULT 'local',amount bigint NOT NULL,currency varchar(3) NOT NULL,ticket_hash varchar(64) NOT NULL UNIQUE,auth_until timestamptz NOT NULL,context_hash varchar(64),csrf_hash varchar(64),auth_state varchar(24) NOT NULL DEFAULT 'PENDING',instrument varchar(32) NOT NULL DEFAULT 'APPROVE',captured bigint NOT NULL DEFAULT 0,canceled bigint NOT NULL DEFAULT 0,partial_cancelable boolean NOT NULL DEFAULT true,approved_at timestamptz,UNIQUE(realm_id,provider_order_id));
CREATE TABLE IF NOT EXISTS psp_operations(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,payment_id uuid NOT NULL REFERENCES psp_payments,kind varchar(16) NOT NULL,amount bigint NOT NULL,key_hash varchar(64) NOT NULL,request_hash varchar(64) NOT NULL,state varchar(24) NOT NULL,transaction_id varchar(80),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),key_until timestamptz NOT NULL,UNIQUE(realm_id,kind,key_hash));
CREATE TABLE IF NOT EXISTS psp_transactions(id varchar(80) PRIMARY KEY,realm_id varchar(80) NOT NULL,payment_id uuid NOT NULL REFERENCES psp_payments,operation_id uuid,kind varchar(16) NOT NULL,amount bigint NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX IF NOT EXISTS psp_one_capture ON psp_transactions(payment_id) WHERE kind='CAPTURE';
CREATE TABLE IF NOT EXISTS psp_webhooks(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,payment_id uuid NOT NULL REFERENCES psp_payments,attempt_id uuid NOT NULL,event_type varchar(32) NOT NULL,operation_id uuid,state varchar(24) NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,next_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE psp_payments ADD COLUMN IF NOT EXISTS return_ciphertext text;
ALTER TABLE psp_payments DROP CONSTRAINT IF EXISTS psp_payments_realm_id_provider_order_id_key;
CREATE INDEX IF NOT EXISTS psp_attempt ON psp_payments(attempt_id);
CREATE TABLE IF NOT EXISTS psp_call_log(id uuid PRIMARY KEY,realm_id varchar(80) NOT NULL,kind varchar(16) NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp());
